// One Taste of Strawberry — the-picture-that-tastes-of-one-20261122-2047
//
// A program that writes one picture of food built on ONE ingredient: a
// single ripe strawberry, macro close-up, one bite taken out of it,
// glistening with juice in warm golden light. The picture is embedded
// below as a base64 PNG and written byte-for-byte to /output/entry.png
// after the program validates it against the bounty gate (whole PNG,
// at most 1,048,576 bytes, at most 1024x1024 pixels).
//
// Run with Node 22: `node main.ts`
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";

const PNG_BASE64 = "";

const MAX_BYTES = 1_048_576;
const MAX_DIMENSION = 1024;
const OUT_PATH = "/output/entry.png";

function fail(message: string): never {
  console.error(`error: ${message}`);
  process.exit(1);
}

function main(): void {
  const png = Buffer.from(PNG_BASE64, "base64");

  // PNG signature: 89 50 4E 47 0D 0A 1A 0A.
  const signature = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
  if (png.length < 33 || !png.subarray(0, 8).equals(signature)) {
    fail("embedded image is not a valid PNG (bad signature)");
  }

  // The first chunk must be IHDR, and the file must end with a whole
  // IEND chunk — otherwise the image is truncated or malformed.
  if (png.subarray(12, 16).toString("latin1") !== "IHDR") {
    fail("embedded image has no IHDR chunk where one belongs");
  }
  const iend = Buffer.from([
    0x00, 0x00, 0x00, 0x00, 0x49, 0x45, 0x4e, 0x44, 0xae, 0x42, 0x60, 0x82,
  ]);
  if (!png.subarray(png.length - 12).equals(iend)) {
    fail("embedded image is missing its IEND trailer (truncated?)");
  }

  // IHDR chunk: width and height are big-endian uint32 at bytes 16 and 20.
  const width = png.readUInt32BE(16);
  const height = png.readUInt32BE(20);
  if (width === 0 || height === 0 || width > MAX_DIMENSION || height > MAX_DIMENSION) {
    fail(`dimensions ${width}x${height} exceed the ${MAX_DIMENSION}x${MAX_DIMENSION} limit`);
  }
  if (png.length > MAX_BYTES) {
    fail(`image is ${png.length} bytes, over the ${MAX_BYTES} byte limit`);
  }

  mkdirSync("/output", { recursive: true });
  writeFileSync(OUT_PATH, png);

  // Read the file back and confirm it is byte-for-byte what we validated.
  const written = readFileSync(OUT_PATH);
  if (!written.equals(png)) {
    fail(`${OUT_PATH} does not match the validated image after writing`);
  }
  const sha256 = createHash("sha256").update(png).digest("hex");
  console.log(`wrote ${OUT_PATH}: ${width}x${height} PNG, ${png.length} bytes, sha256 ${sha256}`);
  console.log("verified: written file is byte-identical to the validated image");
}

main();
